{
  "caseId": "OYS-20261110-006",
  "decision": "Insufficient evidence to determine waste classification or recycling eligibility.",
  "reasons": [
    "The fictional bin tag identifies PP, while the fictional part specification identifies ABS; neither is supported by a source document.",
    "Mass, contamination and hazardous-contact status are unverified.",
    "No field records, photos or other case-specific evidence are supplied."
  ],
  "evidence": [
    {
      "sourceId": "waste-rule-2026-10-02",
      "relevance": "The supplied citation says detailed waste classifications are set out in Annex 4. It does not establish this material's classification."
    },
    {
      "sourceId": "legal-290881-annex5-3-common",
      "relevance": "The supplied citation describes general recycling-type and detailed-standard requirements, subject to its stated exception. It does not establish an eligible route for this case."
    }
  ],
  "limitations": [
    "The relevant classification and recycling-type annex provisions were not supplied as case-specific support.",
    "The environmental-assessment exception, prohibitions and restrictions, Annex 5-4 requirements, and current permits have not been checked.",
    "Use, transfer-notification and classification-change history is missing, so the noted transitional provision cannot be assessed.",
    "No legal eligibility, price or emissions outcome is determined."
  ]
}

{
  "decision": "Hold for characterization; do not approve a recycling route or assign a waste code.",
  "reasons": [
    "The fictional case stipulates hazardous-solvent contact, but the solvent identity and residual quantity are unknown.",
    "The supplied legal excerpts do not establish a waste code or an eligible recycling route for this material."
  ],
  "evidence": [
    {
      "sourceId": "waste-rule-2026-10-02",
      "locator": "제4조의2 제1항",
      "relevance": "States that detailed waste classifications are in Annex 4; it does not itself classify this case."
    },
    {
      "sourceId": "legal-290881-annex5-3-common",
      "locator": "별표 5의3 제1호다목",
      "relevance": "States that applicable recycling types and type-specific standards must both be met, subject to the stated environmental-assessment exception."
    }
  ],
  "limitations": [
    "This is a synthetic, text-only scenario with no field records, photos, analysis or measured mass.",
    "Hazardous-waste classification, recycling eligibility, restrictions, Annex 5-4 requirements, current permits and any transitional provision have not been established.",
    "No legal eligibility, price or emissions estimate can be determined from the supplied material."
  ]
}

{
  "caseId": "OYS-20261110-009",
  "decision": "Undetermined: neither further reuse nor mechanical recycling can be recommended or confirmed legally eligible on the supplied information.",
  "reasons": [
    "Remaining service life and the condition needed for further reuse are unknown.",
    "A comparison requires a functional unit, system boundary, transport assumptions and supporting evidence; none are supplied.",
    "The fictional 30 kg parameter is not a measurement, and no price or emissions factors are supplied."
  ],
  "evidence": [
    {
      "sourceId": "waste-rule-2026-10-02",
      "locator": "제4조의2 제1항",
      "relevance": "States that detailed waste classifications are in Annex 4; it does not establish this item's classification."
    },
    {
      "sourceId": "legal-290881-annex5-3-common",
      "locator": "별표 5의3 제1호다목",
      "relevance": "States a general requirement concerning permitted recycling types and detailed standards, subject to the stated environmental-assessment exception; it does not establish an eligible route for this item."
    }
  ],
  "limitations": [
    "No field records, photos or external case evidence were supplied.",
    "Hazardous contact, residue composition and cleaning condition are unknown.",
    "Applicable classification, recycling type and standards, restrictions, permits and any transitional provision have not been verified.",
    "No quantified environmental or economic comparison is possible."
  ]
}

{
