  "reasons": [
    "The PET offcuts' contamination and hazardous-contact history are unknown.",
    "Mass, region, processor details, quotations and emissions factors are absent.",
    "The supplied general legal provisions do not establish a waste code, permitted recycling type or processor eligibility for this case."
  ],
  "evidence": [
